INSERT INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `seed_version`, `created_at`, `updated_at`) VALUES ('ee82bd25-f975-5314-9b9c-adba475c9918', 'global', NULL, 'Barbell walking lunge', '1. Begin standing with your feet shoulder width apart and a barbell across your upper back.
