INSERT INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `seed_version`, `created_at`, `updated_at`) VALUES ('c50a4b74-054a-5889-aa47-5f00aa9a72ad', 'global', NULL, 'Smith machine overhead shoulder press', '1. To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.
