INSERT INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `seed_version`, `created_at`, `updated_at`) VALUES ('e0bf6eea-c8d9-57bb-a5a9-51dda9ee6673', 'global', NULL, 'JM press', '1. Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest.
