INSERT INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `seed_version`, `created_at`, `updated_at`) VALUES ('8d5d029a-5d93-5581-b979-5d28ca771881', 'global', NULL, 'Tate press', '1. Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.
