INSERT INTO `exercise_library_items` (`id`, `ownership`, `trainer_user_id`, `name`, `instructions`, `primary_muscles_json`, `secondary_muscles_json`, `equipment_json`, `difficulty`, `status`, `slug`, `category_code`, `movement_pattern_code`, `logging_type_code`, `setting`, `mechanic`, `force`, `laterality`, `safety_note`, `source_id`, `source_ref`, `source_name`, `review_status`, `seed_version`, `created_at`, `updated_at`) VALUES ('b7a53b46-7045-5c2b-8a1b-5b4c229a55c5', 'global', NULL, 'Push-ups – close triceps position', '1. Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.
