INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('a1f7265a-2ab4-5357-9a2c-0217fe99b25f', 'a2a6be85-fde8-57f4-8ff0-d9698390fab8', 'step', 1, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('d043327b-29f4-5a27-8e53-f0b6c812f98b', 'a2a6be85-fde8-57f4-8ff0-d9698390fab8', 'step', 2, 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('b5da8702-ac79-59d3-9b39-972674f17a1b', 'a2a6be85-fde8-57f4-8ff0-d9698390fab8', 'step', 3, 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('4508f119-9a8d-5a5c-8223-a48a7bc3e1fa', 'a2a6be85-fde8-57f4-8ff0-d9698390fab8', 'step', 4, 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
