INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('bc2c7494-7e0f-587f-a3cf-c0db836946dc', 'd5ffd4b6-d501-5f65-92cd-0df364b8364f', 'step', 1, 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
