INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('dd776a49-3267-5706-8646-1b3481d7c586', '0e625ce1-2fc8-50ad-83ef-a26e7402fb1d', 'step', 1, 'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('aefcb21d-a07d-5680-8b00-9611a3216c37', '0e625ce1-2fc8-50ad-83ef-a26e7402fb1d', 'step', 2, 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('6d490c1d-2e87-5129-8461-fd3020e46a30', '0e625ce1-2fc8-50ad-83ef-a26e7402fb1d', 'step', 3, 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
