INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('b7b2dc82-4e45-5d11-a468-d258e942dc32', '7b98027c-7e91-5644-8f2d-772a54a500a0', 'step', 1, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('aca27b1f-45fa-5b95-8e71-c94f542c6cb9', '7b98027c-7e91-5644-8f2d-772a54a500a0', 'step', 2, 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('96ba92d6-397b-581f-8311-8e1fb19ed2cd', '7b98027c-7e91-5644-8f2d-772a54a500a0', 'step', 3, 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
