INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('d4b67696-028b-5c3a-921c-534729ccd08f', 'ec7f63a8-25aa-5839-af33-4f8048a611c8', 'step', 1, 'Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
