INSERT INTO `exercise_library_instructions` (`id`, `exercise_library_item_id`, `kind`, `position`, `text`, `lang`, `provenance`) VALUES ('b056ac5e-38bf-51eb-a833-abfc504261bf', 'cca428a4-2b64-5395-86a9-33aa29f5dbe1', 'step', 1, 'To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.', 'en', 'source:free_exercise_db') ON CONFLICT(`id`) DO UPDATE SET `exercise_library_item_id`=excluded.`exercise_library_item_id`, `kind`=excluded.`kind`, `position`=excluded.`position`, `text`=excluded.`text`, `lang`=excluded.`lang`, `provenance`=excluded.`provenance`;
